<?php
$uid = (int)$u['id'];
handle('pocket_add', function () use ($uid) { Pockets::create($uid, (string)$_POST['name'], (string)$_POST['kind'], (string)$_POST['target'], ($_POST['date'] ?? '') ?: null); return 'Pocket created.'; });
handle('pocket_move', function () use ($uid) { $d = $_POST['dir'] === 'out' ? 'out' : 'in'; Auth::verifyPin($uid, (string)($_POST['pin'] ?? '')); Pockets::move($uid, (int)$_POST['id'], cents($_POST['amount'] ?? ''), $d); return $d === 'in' ? 'Moved to pocket.' : 'Moved back to your wallet.'; });
echo page_head('Pockets', 'Separate goals for education, travel, emergencies and monthly expenses.');
echo '<div class="alert info">' . icon('alert') . '<div><strong>Simulated pockets.</strong> These are bookkeeping buckets inside this demo. They are not bank deposits, not savings accounts, and not a regulated financial product.</div></div>';
$ps = rows('SELECT p.*, a.balance FROM pockets p JOIN ledger_accounts a ON a.id=p.account_id WHERE p.user_id=? ORDER BY p.id', [$uid]); $o = '';
foreach ($ps as $p) { $pct = (float)$p['target_amount'] > 0 ? 100 * (float)$p['balance'] / (float)$p['target_amount'] : 0;
  $o .= card($p['name'], '<div class="muted">' . e(type_label($p['pocket_kind'])) . ($p['target_date'] ? ' &middot; target ' . e(fdate($p['target_date'], false)) : '') . '</div><div class="stat sm">' . mny($p['balance']) . '</div>' . progress($pct) . '<p class="hint">' . round($pct) . '% of ' . mny($p['target_amount']) . '</p>' . form_start('pocket_move') . '<input type="hidden" name="id" value="' . (int)$p['id'] . '"><div class="row">' . field('Amount', 'amount', 'text', '', 'required inputmode="decimal"') . select('Direction', 'dir', ['in' => 'Wallet to pocket', 'out' => 'Pocket to wallet'], 'in') . field('PIN', 'pin', 'password', '', 'required inputmode="numeric" maxlength="6"') . '</div>' . btn('Move money', 'secondary sm') . '</form>'); }
echo '<div class="grid g2">' . ($o ?: card('', empty_state('No pockets yet.', 'target'))) . card('New pocket', form_start('pocket_add') . field('Name', 'name', 'text', '', 'required maxlength="80"') . select('Type', 'kind', ['education' => 'Education', 'travel' => 'Travel', 'emergency' => 'Emergency', 'monthly_expense' => 'Monthly expenses', 'custom' => 'Custom'], 'education') . field('Target (BDT)', 'target', 'text', '', 'required inputmode="decimal"') . field('Target date', 'date', 'date', '') . btn('Create pocket') . '</form>') . '</div>';
